def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    low_fixed = []
    high_spenders = []
    desperate_count = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid')
            prev_bids.append(float(bid))
            if bid <= 20:
                low_fixed.append(float(bid))
            if bid >= 80:
                high_spenders.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_low = min(low_fixed) if low_fixed else 15.0

    base = 16.5

    if supply >= 24:
        base = max(base, lowest_low + 1.0)
    elif supply >= 21:
        base = max(base, lowest_low + 2.0)
    elif supply >= 18:
        base = max(base, 22.0)
    else:
        base = max(base, 30.0)

    if len(high_spenders) >= 1 and supply <= 17 and hp > 5 and no_water_days == 0:
        base = min(base, 18.0)

    if desperate_count >= 2:
        base = max(base, 32.0)
    elif desperate_count == 1:
        base = max(base, 24.0)

    if hp <= 2 or no_water_days >= 2:
        base = max(base, 78.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, 48.0)

    if highest_prev >= 120 and supply <= 17 and hp >= 6 and no_water_days == 0:
        base = min(base, 20.0)

    if budget < 40:
        base = min(base, budget)
    elif budget < 80:
        base = min(base, max(24.0, budget * 0.7))
    else:
        base = min(base, budget * 0.55 + 8.0)

    if hp >= 7 and no_water_days == 0 and supply >= 21 and low_fixed:
        target = lowest_low + 2.5
        if target > base:
            base = target

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Identify alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to gauge aggressiveness
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If Cindy was extreme yesterday, she likely continues pressure.
    # We specifically look at Cindy's yesterday bid if present.
    cindy_prev_bid = None
    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive', False):
        prev = opponents_status['Cindy'].get('previous_trace', {})
        if prev and prev.get('bid', None) is not None:
            cindy_prev_bid = float(prev['bid'])

    # Base bid target: ensure we can win water when supply is not huge.
    # Supply bracket: [15,25]
    # If supply is closer to 15, competition matters more.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = 0.0 if supply_ratio < 0.0 else (1.0 if supply_ratio > 1.0 else supply_ratio)

    # Urgency: if we've already gone without water, increase bid.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.6
    else:
        urgency = 0.25

    # HP urgency
    if hp <= 2:
        hp_factor = 1.0
    elif hp <= 4:
        hp_factor = 0.75
    else:
        hp_factor = 0.45

    # Pressure from opponent bids
    pressure = 0.0
    if cindy_prev_bid is not None:
        # Cindy bid was ~121.5 yesterday; if still alive, treat as strong pressure.
        if cindy_prev_bid >= DAILY_SALARY * 1.0:
            pressure = 0.9
        elif cindy_prev_bid >= DAILY_SALARY * 0.7:
            pressure = 0.6
        else:
            pressure = 0.35
    else:
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            pressure = 0.8
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            pressure = 0.55
        else:
            pressure = 0.35

    # Compute target bid
    # More pressure when supply is low.
    low_supply_boost = (1.0 - supply_ratio)
    target = DAILY_SALARY * (0.45 + 0.35 * urgency + 0.25 * hp_factor + 0.25 * pressure + 0.15 * low_supply_boost)

    # If Cindy was extremely high, we match partially to avoid overpaying.
    if cindy_prev_bid is not None and cindy_prev_bid >= DAILY_SALARY * 1.0:
        target = min(target, cindy_prev_bid * 0.85)

    # If my HP is very low, be willing to overmatch.
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)

    # Cap by budget
    bid = float(min(budget, target))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid
